    """
    Las felicitaciones registradas antes de esta regla quedan respaldadas por
    el delegado de su delegación, si tiene uno: así el resultado de un
    período ya medido no cambia por una regla nueva. Las de una delegación
    sin delegado quedan pendientes.
    """
    from django.utils import timezone

    Reconocimiento = apps.get_model("gestion", "Reconocimiento")
    for registro in (Reconocimiento.objects.filter(tipo="felicitacion", respaldada_por__isnull=True)
                     .select_related("delegacion")):
        if registro.delegacion.delegado_id:
            registro.respaldada_por_id = registro.delegacion.delegado_id
            registro.respaldada_el = timezone.now()
            registro.save(update_fields=["respaldada_por", "respaldada_el"])


